{
  "tables": ["account", "trans", "district"],
  "columns": [
    "district.a2",
    "district.a3",
    "district.a4",
    "sum(trans.amount)",
    "round(sum(trans.amount) / district.a4::numeric, 2)",
    "rank() over (order by round(sum(trans.amount) / district.a4::numeric, 2) desc)",
    "avg(order.amount)"
  ],
  "filters": [
    {"table": "trans", "column": "type", "op": "=", "value": "VYDAJ"}
  ]
}

{
  "tables": ["account", "card", "trans", "district"],
  "columns": [
    "account.account_id",
    "district.a2",
    "district.a3",
    "SUM(CASE WHEN trans.type = 'PRIJEM' THEN trans.amount ELSE 0 END) AS total_received",
    "SUM(CASE WHEN trans.type = 'VYDAJ' THEN trans.amount ELSE 0 END) AS total_withdrawn",
    "COUNT(DISTINCT CASE WHEN trans.type = 'PRIJEM' THEN trans.account ELSE NULL END) AS external_counterparties_received",
    "COUNT(DISTINCT CASE WHEN trans.type = 'VYDAJ' THEN trans.account ELSE NULL END) AS external_counterparties_withdrawn"
  ],
  "filters": [
    {
      "table": "card",
      "column": "type",
      "op": "=",
      "value": "gold"
    }
  ]
}

