  "filters": [
    {"table": "frpm", "column": "Low Grade", "op": "=", "value": "6"},
    {"table": "frpm", "column": "High Grade", "op": "=", "value": "8"},
    {"table": "frpm", "column": "Percent (%) Eligible Free (K-12)", "op": ">", "value": "0"},
    {"table": "frpm", "column": "Percent (%) Eligible FRPM (K-12)", "op": ">", "value": "0"}
