{
  "tables": ["attendance", "budget", "event", "expense"],
  "columns": [
    "event.event_name",
    "SUM(CASE WHEN expense.expense_description LIKE '%bottled drinking water%' THEN expense.cost ELSE 0 END) / COUNT(attendance.link_to_member) AS avg_water_cost"
  ],
  "filters": [
    { "table": "event", "column": "status", "op": "=", "value": "closed" }
  ]
}

{
  "tables": ["budget", "expense", "event"],
  "columns": ["budget.amount"],
  "filters": [
    {"table": "event", "column": "event_date", "op": "BETWEEN", "value": "2019-09-01 AND 2019-09-30"},
    {"table": "event", "column": "event_id", "op": "IN", "value": "(SELECT link_to_event FROM expense WHERE expense_description = 'Pizza')"},
    {"table": "budget", "column": "link_to_event", "op": "IN", "value": "(SELECT link_to_event FROM event WHERE event_date BETWEEN '2019-09-01' AND '2019-09-30')"}
  ]
}

{
  "tables": ["expense", "budget"],
  "columns": ["expense.expense_description", "budget.category", "SUM(expense.cost)"],
  "filters": [
    {"table": "expense", "column": "link_to_budget", "op": "IN", "value": "(SELECT budget_id FROM budget WHERE event_status = 'approved' AND link_to_event IN (SELECT event_id FROM event WHERE event_date LIKE '2023-10-%'))"},
    {"table": "expense", "column": "approved", "op": "=", "value": "true"}
  ]
}

